package generrors

import (
	"fmt"
	"go/format"
	"go/types"
	"net/http"
	"strconv"
	"strings"

	"github.com/nanostack-dev/nanostack-framework/gen"
	"github.com/nanostack-dev/nanostack-framework/gen/internal/importset"
)

const faultImport = "github.com/nanostack-dev/nanostack-framework/core/fault"

func (c *catalogue) fullCode(d decl) string { return c.namespace + "." + d.code }

func (c *catalogue) typeURI(d decl) string { return c.typeBase + "/" + c.namespace + "/" + d.code }

// renderer holds the import names of one generated file. Every package the
// file names goes through im, so no import collides with another import, with
// a name the package declares, or with a generated name; and an import is
// written exactly when the rendered code uses it.
type renderer struct {
	c     *catalogue
	im    *importset.Set
	fault string // name of the core/fault import
}

func (r *renderer) qualifier(p *types.Package) string {
	if p.Path() == r.c.pkgPath {
		return ""
	}
	preferred := p.Name()
	if alias, ok := r.c.aliases[p.Path()]; ok {
		preferred = alias
	}
	return r.im.Add(p.Path(), preferred)
}

func (r *renderer) typeString(t types.Type) string { return types.TypeString(t, r.qualifier) }

// renderGo writes the generated Go file. Output depends only on the
// declaration, in declaration order, so two runs give identical bytes.
// scope lists the package-level names the package declares by hand.
func renderGo(c *catalogue, scope []string) ([]byte, error) {
	r := &renderer{c: c, im: importset.New(c.pkgPath)}
	r.im.Block(scope...)
	// Identifiers the generated methods declare locally: an import under one
	// of these names would be shadowed where it is used.
	r.im.Block(kindsVar, "e", "c", "msg", "cause")
	for _, d := range c.errors {
		r.im.Block(d.name, d.name+"Error", "Err"+d.name)
	}
	r.fault = r.im.Add(faultImport, "fault")

	var b strings.Builder
	w := func(format string, args ...any) { fmt.Fprintf(&b, format, args...) }

	w("// %s lists every %s error in declaration order, for documentation and\n", kindsVar, c.namespace)
	w("// tests.\n")
	w("var %s = []*%s.Kind{\n", kindsVar, r.fault)
	for _, d := range c.errors {
		w("\tErr%s,\n", d.name)
	}
	w("}\n\n")

	w("// Compile-time checks: the declaration interface stays referenced, and every\n")
	w("// generated error satisfies the problem contracts.\n")
	w("var (\n\t_ %s\n", c.iface)
	for _, d := range c.errors {
		w("\t_ %s.Coded    = (*%sError)(nil)\n", r.fault, d.name)
		w("\t_ %s.Detailed = (*%sError)(nil)\n", r.fault, d.name)
	}
	w(")\n")

	for _, d := range c.errors {
		r.renderDecl(&b, d)
	}

	var file strings.Builder
	fmt.Fprintf(&file, "// Code generated by nano gen errors from %s. DO NOT EDIT.\n\n", c.file)
	fmt.Fprintf(&file, "package %s\n\n", c.pkg)
	r.im.Write(&file)
	file.WriteString(b.String())
	src, err := format.Source([]byte(file.String()))
	if err != nil {
		return nil, gen.Errorf("", 0, "report this nano gen errors bug with the declaration",
			"format generated code: %v\n%s", err, file.String())
	}
	return src, nil
}

func (r *renderer) renderDecl(b *strings.Builder, d decl) {
	c := r.c
	w := func(format string, args ...any) { fmt.Fprintf(b, format, args...) }
	typ := d.name + "Error"
	kind := "Err" + d.name
	code := c.fullCode(d)

	w("\n// %s is the catalogue entry of %s.\n", kind, typ)
	w("// errors.Is(err, %s) reports whether err is, or wraps, one.\n", kind)
	w("var %s = %s.NewKind(%q, %d, %q, %q)\n\n", kind, r.fault, code, d.status, d.title, c.typeURI(d))

	w("// %s is %s (HTTP %d %s).\n", typ, code, d.status, http.StatusText(d.status))
	writeDoc(b, d.doc)
	w("type %s struct {\n", typ)
	for _, p := range d.params {
		w("\t%s %s\n", p.field, r.typeString(p.typ))
	}
	w("\tcause error\n}\n\n")

	w("// %s returns a new %s.\n", d.name, typ)
	writeDoc(b, d.doc)
	params := make([]string, len(d.params))
	inits := make([]string, len(d.params))
	for i, p := range d.params {
		params[i] = p.name + " " + r.typeString(p.typ)
		inits[i] = p.field + ": " + p.name
	}
	w(
		"func %s(%s) *%s {\n\treturn &%s{%s}\n}\n\n",
		d.name,
		strings.Join(params, ", "),
		typ,
		typ,
		strings.Join(inits, ", "),
	)

	w("// Wrap returns a copy of e that carries cause. errors.Is and errors.As reach\n")
	w("// the cause; the problem writer never sends it to clients.\n")
	w("func (e *%s) Wrap(cause error) *%s {\n\tc := *e\n\tc.cause = cause\n\treturn &c\n}\n\n", typ, typ)
	w("// Unwrap returns the cause given to Wrap, or nil.\n")
	w("func (e *%s) Unwrap() error { return e.cause }\n\n", typ)
	w("// Is reports whether target is %s.\n", kind)
	w("func (e *%s) Is(target error) bool { return target == %s }\n\n", typ, kind)

	w("// Error returns the code, the detail (or title and fields) and the cause.\n")
	w("func (e *%s) Error() string {\n", typ)
	w("\tmsg := %s\n", r.errorMessage(d))
	w("\tif e.cause != nil {\n\t\tmsg += \": \" + e.cause.Error()\n\t}\n\treturn msg\n}\n\n")

	w("// ProblemType returns %q.\n", c.typeURI(d))
	w("func (*%s) ProblemType() string { return %s.ProblemType() }\n\n", typ, kind)
	w("// ProblemStatus returns %d.\n", d.status)
	w("func (*%s) ProblemStatus() int { return %s.ProblemStatus() }\n\n", typ, kind)
	w("// ProblemTitle returns %q.\n", d.title)
	w("func (*%s) ProblemTitle() string { return %s.ProblemTitle() }\n\n", typ, kind)
	w("// ProblemCode returns %q.\n", code)
	w("func (*%s) ProblemCode() string { return %s.ProblemCode() }\n\n", typ, kind)
	if d.detail == "" {
		w("// ProblemDetail returns \"\": the declaration has no detail.\n")
		w("func (*%s) ProblemDetail() string { return \"\" }\n", typ)
		return
	}
	w("// ProblemDetail renders %q.\n", d.detail)
	f, args := r.detailFormat(d)
	w("func (e *%s) ProblemDetail() string {\n\treturn %s\n}\n", typ, r.sprintf(f, args))
}

func writeDoc(b *strings.Builder, doc string) {
	if doc == "" {
		return
	}
	b.WriteString("//\n")
	for line := range strings.SplitSeq(doc, "\n") {
		if line == "" {
			b.WriteString("//\n")
			continue
		}
		b.WriteString("// " + line + "\n")
	}
}

// detailFormat turns "Invoice {id} was paid at {paidAt}." into a Sprintf
// format and its arguments.
func (r *renderer) detailFormat(d decl) (string, []string) {
	var f strings.Builder
	var args []string
	rest := d.detail
	for {
		m := placeholderPattern.FindStringSubmatchIndex(rest)
		if m == nil {
			f.WriteString(strings.ReplaceAll(rest, "%", "%%"))
			break
		}
		f.WriteString(strings.ReplaceAll(rest[:m[0]], "%", "%%"))
		f.WriteString("%v")
		name := rest[m[2]:m[3]]
		for _, p := range d.params {
			if p.name == name {
				args = append(args, r.fieldExpr(p))
			}
		}
		rest = rest[m[1]:]
	}
	return f.String(), args
}

func (r *renderer) fieldExpr(p param) string {
	if p.isTime {
		return "e." + p.field + ".Format(" + r.im.Add("time", "time") + ".RFC3339)"
	}
	return "e." + p.field
}

// errorMessage is the expression for Error() before the cause is appended.
func (r *renderer) errorMessage(d decl) string {
	code := r.c.fullCode(d)
	if d.detail != "" {
		f, args := r.detailFormat(d)
		return r.sprintf(strings.ReplaceAll(code, "%", "%%")+": "+f, args)
	}
	if len(d.params) == 0 {
		return strconv.Quote(code + ": " + d.title)
	}
	pairs := make([]string, len(d.params))
	args := make([]string, len(d.params))
	for i, p := range d.params {
		pairs[i] = p.name + "=%v"
		args[i] = r.fieldExpr(p)
	}
	f := strings.ReplaceAll(code+": "+d.title, "%", "%%") + " (" + strings.Join(pairs, ", ") + ")"
	return r.sprintf(f, args)
}

// sprintf renders a Sprintf call, importing fmt only when it emits one, or a
// plain string literal when there is nothing to format.
func (r *renderer) sprintf(format string, args []string) string {
	if len(args) == 0 {
		return strconv.Quote(strings.ReplaceAll(format, "%%", "%"))
	}
	return r.im.Add("fmt", "fmt") + ".Sprintf(" + strconv.Quote(format) + ", " + strings.Join(args, ", ") + ")"
}
